import { expect } from "chai"
import sinon from "sinon"

import settingsData from "../settings.json" with { type: "json" }

import { APIHandler } from "../src/modules/APIHandler"
import { SettingsJSON } from "../src/types/settings"

describe("APIHandler", () => {
  let apiHandler: APIHandler
  let fetchStub: sinon.SinonStub

  beforeEach(() => {
    apiHandler = new APIHandler(settingsData as SettingsJSON)
    fetchStub = sinon.stub(globalThis, "fetch")
  })

  afterEach(() => {
    fetchStub.restore()
  })

  it("builds the archive url for a specific page", () => {
    expect(apiHandler.buildUrl("Kugelbuch", 2)).to.equal(
      "https://www.chess.com/service/player-game-archive-v2/chesscom.game_gateway.v2.GameGatewayService/HydrateGamesByCriteria?username=kugelbuch&page=2"
    )
  })

  it("resolves the player uuid and loads additional pages until the selected interval is exhausted", async () => {
    const now = Math.floor(Date.now() / 1000)
    const profileHtml = `
      <div class="cc-section profile-header-container" data-username="Kugelbuch" data-user-id="123" data-user-uuid="uuid-123"></div>
    `

    const pageOneResponse = {
      hydratedGames: [
        {
          game: {
            key: "page-1-game-1",
            endedAt: new Date((now - 60 * 60) * 1000).toISOString(),
            timeClass: "TIME_CLASS_RAPID",
            chessGame: {
              whitePlayer: {
                result: "PLAYER_RESULT_WIN",
                finalRating: 1000,
                client: "Chesscom-iOS/4.10.24.24677 (iPhone; iOS 26.6)",
                displayName: "Kugelbuch"
              },
              blackPlayer: {
                result: "PLAYER_RESULT_LOSE",
                finalRating: 1000,
                client: "LC6;chrome/151.0.0/browser;Windows 10",
                displayName: "Opponent"
              }
            }
          },
          analysisMetadata: {
            whitePlayerMetadata: { accuracy: 83.1 },
            blackPlayerMetadata: null
          }
        },
        {
          game: {
            key: "page-1-game-2",
            endedAt: new Date((now - 60 * 60 * 13) * 1000).toISOString(),
            timeClass: "TIME_CLASS_BLITZ",
            chessGame: {
              whitePlayer: {
                result: "PLAYER_RESULT_WIN",
                finalRating: 1000,
                client: "LC6;chrome/151.0.0/browser;Windows 10",
                displayName: "Opponent"
              },
              blackPlayer: {
                result: "PLAYER_RESULT_LOSE",
                finalRating: 1000,
                client: "Chesscom-iOS/4.10.24.24677 (iPhone; iOS 26.6)",
                displayName: "Kugelbuch"
              }
            }
          },
          analysisMetadata: {
            whitePlayerMetadata: null,
            blackPlayerMetadata: null
          }
        }
      ],
      pagination: {
        totalSize: 2,
        pageSize: 50,
        currentPage: 1
      }
    }

    fetchStub
      .onFirstCall()
      .resolves({ ok: true, text: async () => profileHtml } as Response)
    fetchStub.onSecondCall().resolves({
      ok: true,
      json: async () => pageOneResponse
    } as Response)

    const data = await apiHandler.fetchChessData("Kugelbuch", "last 12 hours")

    expect(fetchStub.callCount).to.equal(2)
    expect(fetchStub.firstCall.args[0]).to.equal(
      "https://www.chess.com/member/kugelbuch"
    )
    expect(fetchStub.secondCall.args[0]).to.equal(
      "https://www.chess.com/service/player-game-archive-v2/chesscom.game_gateway.v2.GameGatewayService/HydrateGamesByCriteria"
    )
    expect(data.games).to.have.length(1)
    expect(data.games[0].uuid).to.equal("page-1-game-1")
    expect(data.games[0].white.username).to.equal("Kugelbuch")
    expect(data.games[0].white.client).to.include("Chesscom-iOS")
    expect(data.games[0].accuracies?.white).to.equal(83.1)
    expect(data.games[0].accuracies?.black).to.equal(undefined)
    expect(data.games[0].time_class).to.equal("rapid")
  })
})

import { SettingsJSON, TimeInterval } from "../types/settings"
import {
  ApiChessData,
  ApiGame,
  ApiPlayer,
  HydratedGameResponse,
  HydratedGamesResponse
} from "../types/apidata"

import { isWithinTimeInterval } from "./TimeIntervalUtils"

/**
 * Utility class to handle API requests for chess data.
 */
export class APIHandler {
  private FETCH_MAX_RETRIES: number
  private FETCH_RETRY_DELAY: number
  private api: SettingsJSON["api"]

  /**
   * Creates an instance of APIHandler.
   * @param {SettingsJSON} settingsJSON - The JSON object containing settings.
   */
  constructor(settingsJSON: SettingsJSON) {
    this.FETCH_MAX_RETRIES = settingsJSON.FETCH_MAX_RETRIES
    this.FETCH_RETRY_DELAY = settingsJSON.FETCH_RETRY_DELAY
    this.api = settingsJSON.api
  }

  /**
   * Retrieves chess data for a given username.
   * @param {string} username - The username for which to fetch chess data.
   * @returns {Promise<ApiChessData>} A Promise that resolves to the fetched chess data.
   * @throws {string} Throws an error if the maximum number of retries is exceeded.
   */
  async getChessData(
    username: string,
    timeInterval: TimeInterval
  ): Promise<ApiChessData> {
    let retryCount = 0

    while (retryCount < this.FETCH_MAX_RETRIES) {
      try {
        return await this.fetchChessData(username, timeInterval)
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
      } catch (error: any) {
        if (error?.code === 301) break

        if (error?.code === 404) throw `User ${username} not found`

        retryCount++
        if (retryCount < this.FETCH_MAX_RETRIES)
          await new Promise((resolve) =>
            setTimeout(resolve, this.FETCH_RETRY_DELAY)
          )
      }
    }
    throw "Max retries exceeded"
  }

  /**
   * Fetches chess data from a given URL.
   *
   * @param {string} url - The URL from which to fetch chess data.
   * @returns {Promise<ApiChessData>} A Promise that resolves to the fetched chess data.
   */
  async fetchChessData(
    username: string,
    timeInterval: TimeInterval
  ): Promise<ApiChessData> {
    const resolvedUser = await this.resolvePlayerIdentity(username)
    const games: ApiGame[] = []
    let page = this.api.defaultPage
    const pageSize = 50
    // const bounds = getTimeIntervalBounds(timeInterval)

    while (true) {
      const response = await fetch(this.api.archiveEndpoint, {
        method: "POST",
        cache: "no-store",
        headers: {
          "Content-Type": "application/json",
          "User-Agent": "Mozilla/5.0",
          Accept: "application/json",
          Origin: "https://www.chess.com",
          Referer: "https://www.chess.com/"
        },
        body: JSON.stringify({
          criteria: {
            username: resolvedUser.username,
            playerId: resolvedUser.uuid,
            timeClasses: [
              "TIME_CLASS_HYPERBULLET",
              "TIME_CLASS_BULLET",
              "TIME_CLASS_BLITZ",
              "TIME_CLASS_RAPID",
              "TIME_CLASS_CLASSICAL"
            ],
            isVsComputer: false,
            isVsCoach: false,
            page,
            pageSize
            // gameEndTimeFrom: bounds.start,
            // gameEndTimeTo: bounds.end
          },
          fieldMask: "game,analysisMetadata"
        })
      })

      if (!response.ok) {
        const text = await response.text()
        throw Object.assign(
          new Error(
            `Archive request failed (${response.status}): ${text.slice(0, 500)}`
          ),
          { code: response.status }
        )
      }

      const data: HydratedGamesResponse = await response.json()
      const normalizedGames = (data?.hydratedGames ?? []).map((game) =>
        this.normalizeHydratedGame(game)
      )
      const pageGames = normalizedGames.filter((game) =>
        isWithinTimeInterval(game.end_time, timeInterval)
      )

      games.push(...pageGames)

      if (normalizedGames.length < pageSize) break

      const oldestGame = normalizedGames[normalizedGames.length - 1]
      if (
        !oldestGame ||
        !this.checkTimeInterval(oldestGame.end_time, timeInterval)
      )
        break

      page++
    }

    return { games }
  }

  /**
   * Builds the URL for fetching chess data for a given username.
   * @param {string} username - The username for which to build the URL.
   * @returns {string} The built URL for fetching chess data.
   */
  buildUrl(username: string, page?: number): string {
    const effectivePage = page ?? this.api.defaultPage
    const params = new URLSearchParams({
      username: username.toLowerCase(),
      page: effectivePage.toString()
    })

    return `${this.api.archiveEndpoint}?${params.toString()}`
  }

  private async resolvePlayerIdentity(username: string): Promise<{
    username: string
    uuid: string
    userId: string
  }> {
    const profileUrl = `https://www.chess.com/member/${encodeURIComponent(
      username.trim().toLowerCase()
    )}`

    const html = await this.fetchHtml(profileUrl, {
      Referer: "https://www.chess.com/"
    })

    const itemPattern =
      /<div\s+class="cc-section\s+profile-header-container"[^>]*\bdata-username="([^"]+)"[^>]*\bdata-user-id="([^"]+)"[^>]*\bdata-user-uuid="([^"]+)"/i
    const match = html.match(itemPattern)

    if (!match) {
      throw Object.assign(
        new Error(`No profile header with user UUID found for ${username}`),
        { code: 404 }
      )
    }

    return {
      username: String(match[1]),
      userId: String(match[2]),
      uuid: String(match[3])
    }
  }

  private async fetchHtml(
    url: string,
    extraHeaders: Record<string, string> = {}
  ): Promise<string> {
    const res = await fetch(url, {
      headers: {
        "User-Agent": "Mozilla/5.0",
        Accept:
          "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "en-US,en;q=0.9",
        ...extraHeaders
      }
    })

    const text = await res.text()
    if (!res.ok) {
      throw Object.assign(
        new Error(
          `Request failed (${res.status}) for ${url}: ${text.slice(0, 500)}`
        ),
        { code: res.status }
      )
    }

    return text
  }

  private normalizeHydratedGame(game: HydratedGameResponse): ApiGame {
    const whitePlayer = game.game.chessGame.whitePlayer
    const blackPlayer = game.game.chessGame.blackPlayer

    return {
      url: `https://www.chess.com/game/live/${game.game.key}`,
      pgn: "",
      time_control: "",
      end_time: Math.floor(new Date(game.game.endedAt).getTime() / 1000),
      rated: true,
      accuracies: {
        white:
          game.analysisMetadata?.whitePlayerMetadata?.accuracy ?? undefined,
        black: game.analysisMetadata?.blackPlayerMetadata?.accuracy ?? undefined
      },
      tcn: "",
      uuid: game.game.key,
      initial_setup: "",
      fen: "",
      time_class: this.normalizeTimeClass(game.game.timeClass),
      rules: "chess",
      white: this.normalizePlayer(whitePlayer),
      black: this.normalizePlayer(blackPlayer)
    }
  }

  private normalizePlayer(
    player: HydratedGameResponse["game"]["chessGame"]["whitePlayer"]
  ): ApiPlayer {
    return {
      rating: player.finalRating ?? 0,
      result: this.normalizePlayerResult(player.result),
      "@id": player.key ?? player.uuid ?? "",
      username: player.displayName ?? "",
      uuid: player.uuid ?? player.key ?? "",
      client: player.client,
      displayName: player.displayName
    }
  }

  private normalizePlayerResult(result: string): string {
    const upper = result.toUpperCase()

    if (upper.includes("WIN")) return "win"
    if (upper.includes("DRAW") || upper.includes("AGREE")) return "agreed"
    if (
      upper.includes("LOSE") ||
      upper.includes("TIMEOUT") ||
      upper.includes("RESIGN") ||
      upper.includes("ABANDON") ||
      upper.includes("CHECKMATE")
    )
      return "lose"

    return result.toLowerCase()
  }

  private normalizeTimeClass(timeClass: string): string {
    const normalized = timeClass.toLowerCase()

    if (normalized.includes("hyperbullet")) return "bullet"
    if (normalized.includes("bullet")) return "bullet"
    if (normalized.includes("blitz")) return "blitz"
    if (normalized.includes("rapid")) return "rapid"
    if (normalized.includes("classical")) return "rapid"

    return normalized
  }

  private shouldStopFetching(
    games: ApiGame[],
    timeInterval: TimeInterval
  ): boolean {
    const oldestGame = games[games.length - 1]
    if (!oldestGame) return true

    return !this.checkTimeInterval(oldestGame.end_time, timeInterval)
  }

  private checkTimeInterval(
    endTime: number,
    timeInterval: TimeInterval
  ): boolean {
    return isWithinTimeInterval(endTime, timeInterval)
  }
}

import { DateTime } from "luxon"

import { TimeInterval } from "../types/settings"

const TIME_ZONE = "America/Los_Angeles"

const intervalDurations: Record<TimeInterval, { hours: number }> = {
  "last 6 hours": { hours: 6 },
  "last 12 hours": { hours: 12 },
  "last 3 days": { hours: 72 },
  "last week": { hours: 168 },
  "last month": { hours: 720 }
}

export function parseGameEndTime(
  gameEndTime: number | string | undefined
): number {
  if (typeof gameEndTime === "number") return gameEndTime

  if (typeof gameEndTime !== "string") return Number.NaN

  const parsedEndTime = DateTime.fromFormat(gameEndTime, "MMM d, yyyy", {
    zone: TIME_ZONE
  })

  if (!parsedEndTime.isValid) return Number.NaN

  return Math.floor(
    Math.min(parsedEndTime.endOf("day").toSeconds(), Date.now() / 1000)
  )
}

export function isWithinTimeInterval(
  endTime: number,
  timeInterval: TimeInterval
): boolean {
  const { start, end } = getTimeIntervalBounds(timeInterval)

  return endTime >= start && endTime <= end
}

export function getTimeIntervalBounds(timeInterval: TimeInterval): {
  start: number
  end: number
} {
  const now = DateTime.now().setZone(TIME_ZONE)
  const end = Math.floor(Date.now() / 1000)
  const start = Math.floor(
    now.minus(intervalDurations[timeInterval]).toSeconds()
  )

  return { start, end }
}

import { Settings, SettingsJSON } from "../../src/types/settings"
import { SettingsStorage } from "../../src/types/wrapper"

import settingsData from "../../settings.json" with { type: "json" }

const { defaultSettings } = settingsData as SettingsJSON

/**
 * A mock implementation of the SettingsStorage interface for testing purposes.
 */
export class MockSettingsStorage implements SettingsStorage {
  private settings: Settings

  /**
   * Creates an instance of MockSettingsStorage.
   *
   * @param {any} [settings] - Optional initial settings data.
   */
  constructor(settings: Settings = defaultSettings) {
    this.settings = settings
  }

  /**
   * Retrieves stored settings asynchronously.
   *
   * @returns {Promise<any>} A Promise that resolves with the stored settings.
   */
  async getStoredSettings(): Promise<Settings> {
    return this.settings
  }

  /**
   * Saves settings asynchronously.
   *
   * @param {any} settings - The settings data to be saved.
   * @returns {Promise<void>} A Promise that resolves once the settings are saved.
   */
  async saveSettings(settings: Settings): Promise<void> {
    this.settings = settings
  }
}

import { UiWindow } from "../../src/types/wrapper"

/**
 * Mock implementation of the UiWindow interface using JSDOM.
 */
export class MockUiWindow implements UiWindow {
  private window: Window & typeof globalThis

  private document: Document

  protected dom: string = "<!doctype html><html><body></body></html>"

  protected domOptions: Record<string, string | number | boolean> = {
    url: "https://chess.com/",
    referrer: "https://chess.com/",
    contentType: "text/html",
    includeNodeLocations: true,
    storageQuota: 10000000
  }

  /**
   * Initializes the JSDOM instance and assigns the window and document properties.
   * JSDOM is lazy loaded to avoid putting it in production build.
   */
  async initialize() {
    const { JSDOM } = await import("jsdom")
    const dom = new JSDOM(this.dom, this.domOptions)

    this.window = dom.window as unknown as Window & typeof globalThis
    this.document = dom.window.document
  }

  /**
   * Returns the mock Window object.
   *
   * @returns {Window} The mock Window object.
   */
  getWindow(): Window {
    if (!this.window) throw new Error("Window not initialized")
    return this.window
  }

  /**
   * Returns the Document object associated with the mock Window.
   *
   * @returns {Document} The Document object.
   */
  getDocument(): Document {
    if (!this.document) throw new Error("Document not initialized")
    return this.document
  }
}

import { expect } from "chai"
import sinon from "sinon"
import { DateTime } from "luxon"

import { StatsCalculator } from "../src/modules/StatsCalculator"

describe("StatsCalculator", () => {
  let statsCalculator: StatsCalculator
  let nowStub: sinon.SinonStub

  beforeEach(() => {
    statsCalculator = new StatsCalculator()

    const fixedNow = DateTime.local(2026, 8, 26, 20, 0).toMillis()
    nowStub = sinon.stub(Date, "now").returns(fixedNow)
  })

  afterEach(() => {
    nowStub.restore()
  })

  it("keeps games in the rolling six hour interval", () => {
    const now = Math.floor(Date.now() / 1000)
    const legacyGame = {
      gameTimeClass: "lightning",
      gameEndTime: now - 60 * 60 * 2,
      user1: {
        username: "Opponent"
      },
      user2: {
        username: "Alex-11211"
      },
      user1Result: 0,
      user2Result: 1,
      user1Accuracy: null,
      user2Accuracy: null
    }

    const filteredGames = statsCalculator.filterGames(
      [legacyGame as never],
      ["bullet"],
      "last 6 hours"
    )

    expect(filteredGames).to.have.lengthOf(1)
  })

  it("uses the latest client info and ignores missing accuracy metadata", () => {
    const now = Math.floor(Date.now() / 1000)

    const games = [
      {
        end_time: now - 60,
        time_class: "rapid",
        white: {
          username: "Kugelbuch",
          result: "win",
          "@id": "1",
          uuid: "1",
          rating: 1200,
          client: "Chesscom-iOS/4.10.24.24677 (iPhone; iOS 26.6)"
        },
        black: {
          username: "Opponent",
          result: "lose",
          "@id": "2",
          uuid: "2",
          rating: 1200,
          client: "LC6;chrome/151.0.0/browser;Windows 10"
        },
        accuracies: {
          white: null,
          black: null
        }
      },
      {
        end_time: now - 120,
        time_class: "blitz",
        white: {
          username: "Kugelbuch",
          result: "win",
          "@id": "3",
          uuid: "3",
          rating: 1200,
          client: "LC6;chrome/151.0.0/browser;Windows 10"
        },
        black: {
          username: "Opponent",
          result: "lose",
          "@id": "4",
          uuid: "4",
          rating: 1200,
          client: "Chesscom-iOS/4.10.24.24677 (iPhone; iOS 26.6)"
        },
        accuracies: {
          white: 80,
          black: null
        }
      }
    ]

    const stats = statsCalculator.calculateStats(
      games as never,
      ["bullet", "blitz", "rapid"],
      "last 6 hours",
      "Kugelbuch"
    )

    expect(stats.accuracy.avg).to.equal(80)
    expect(stats.accuracy.wld.games).to.equal(1)
    expect(stats.device?.platform).to.equal("phone")
    expect(stats.device?.icon).to.equal("mdi-cellphone")
    expect(stats.device?.summary).to.equal("Player last played on phone")
  })
})

import { ApiGame } from "../types/apidata"
import { GameMode, TimeInterval } from "../types/settings"
import { DeviceInfo, Stats, Wld } from "../types/stats"

import { isWithinTimeInterval, parseGameEndTime } from "./TimeIntervalUtils"

/**
 * A utility class for calculating chess statistics based on filtered games.
 */
export class StatsCalculator {
  private readonly gameModeMap: Record<string, GameMode> = {
    hyperbullet: "bullet",
    lightning: "bullet",
    bullet: "bullet",
    blitz: "blitz",
    standard: "rapid",
    rapid: "rapid",
    classical: "rapid"
  }

  /**
   * Calculates chess statistics for filtered games.
   *
   * @param {ApiGame[]} games - The array of API games.
   * @param {GameMode[]} gameModes - The array of game modes to include.
   * @param {TimeInterval} timeInterval - The time interval for filtering games.
   * @param {string} username - The username for identifying player's games.
   * @returns {Stats} The calculated statistics.
   */
  calculateStats(
    games: ApiGame[],
    gameModes: GameMode[],
    timeInterval: TimeInterval,
    username: string
  ): Stats {
    const device = this.getLatestDeviceInfo(games, username)
    games = this.filterGames(games, gameModes, timeInterval)

    const stats: Stats = {
      wld: { wins: 0, loses: 0, draws: 0, games: games.length },
      accuracy: {
        avg: 0,
        wld: {
          wins: 0,
          loses: 0,
          draws: 0,
          games: games.length
        }
      },
      device
    }

    games.forEach((game) => {
      const playerKey = this.getPlayerKey(game, username)

      if (!playerKey) {
        console.error("Could not determine player for game", game)
        return
      }

      const result = this.transformResult(this.getPlayerResult(game, playerKey))
      if (!result) return
      stats.wld[result]++

      const accuracy = this.getPlayerAccuracy(game, playerKey)
      if (accuracy !== undefined) {
        stats.accuracy.avg += accuracy || 0
        stats.accuracy.wld[result]++
      } else stats.accuracy.wld.games--
    })

    stats.accuracy.avg = parseFloat(
      (stats.accuracy.avg / stats.accuracy.wld.games).toFixed(0)
    )
    if (isNaN(stats.accuracy.avg)) stats.accuracy.avg = 0

    return stats
  }

  /**
   * Filters games based on game modes and time intervals.
   *
   * @param {ApiGame[]} games - The array of API games.
   * @param {GameMode[]} gameModes - The array of game modes to include.
   * @param {TimeInterval} timeInterval - The time interval for filtering games.
   * @returns {ApiGame[]} The filtered array of games.
   */
  filterGames(
    games: ApiGame[],
    gameModes: GameMode[],
    timeInterval: TimeInterval
  ): ApiGame[] {
    return games.filter((game) => {
      const normalizedGameMode = this.gameModeMap[this.getGameTimeClass(game)]

      return (
        !!normalizedGameMode &&
        gameModes.includes(normalizedGameMode) &&
        this.checkTimeInterval(this.getGameEndTime(game), timeInterval)
      )
    })
  }

  /**
   * Checks if a game end time falls within the specified time interval.
   *
   * @param {number} end_time - End time of the chess game in seconds since epoch.
   * @param {TimeInterval} time_interval - Time interval as a string (e.g., "today", "last week").
   * @returns {boolean} True if the game end time falls within the specified time interval, otherwise false.
   */
  checkTimeInterval(end_time: number, time_interval: TimeInterval): boolean {
    return isWithinTimeInterval(end_time, time_interval)
  }

  private getGameTimeClass(game: ApiGame): string {
    return (
      game.time_class ||
      (game as unknown as { gameTimeClass?: string }).gameTimeClass ||
      ""
    )
  }

  private getGameEndTime(game: ApiGame): number {
    const legacyGame = game as unknown as { gameEndTime?: string }
    return parseGameEndTime(game.end_time ?? legacyGame.gameEndTime)
  }

  private getPlayerKey(
    game: ApiGame,
    username: string
  ): "white" | "black" | "user1" | "user2" | undefined {
    const normalizedUsername = username.toLowerCase()
    const white = game.white?.username?.toLowerCase()
    const black = game.black?.username?.toLowerCase()

    if (white === normalizedUsername) return "white"
    if (black === normalizedUsername) return "black"

    const legacyGame = game as unknown as {
      user1?: { username?: string }
      user2?: { username?: string }
    }

    if (legacyGame.user1?.username?.toLowerCase() === normalizedUsername)
      return "user1"
    if (legacyGame.user2?.username?.toLowerCase() === normalizedUsername)
      return "user2"

    return undefined
  }

  private getPlayerResult(
    game: ApiGame,
    playerKey: "white" | "black" | "user1" | "user2"
  ): string {
    if (playerKey === "white" || playerKey === "black") {
      return game[playerKey].result
    }

    const legacyGame = game as unknown as {
      user1Result?: number
      user2Result?: number
    }

    const legacyResult =
      playerKey === "user1" ? legacyGame.user1Result : legacyGame.user2Result

    if (legacyResult === 1) return "win"
    if (legacyResult === 0.5) return "agreed"
    return "lose"
  }

  private getPlayerAccuracy(
    game: ApiGame,
    playerKey: "white" | "black" | "user1" | "user2"
  ): number | undefined {
    if (playerKey === "white" || playerKey === "black") {
      return game.accuracies?.[playerKey] ?? undefined
    }

    const legacyGame = game as unknown as {
      user1Accuracy?: number | null
      user2Accuracy?: number | null
    }

    return playerKey === "user1"
      ? (legacyGame.user1Accuracy ?? undefined)
      : (legacyGame.user2Accuracy ?? undefined)
  }

  private getLatestDeviceInfo(
    games: ApiGame[],
    username: string
  ): DeviceInfo | undefined {
    for (const game of games) {
      const player = this.getPlayer(game, username)
      const client = player?.client?.trim()
      if (!client) continue

      return this.parseClientInfo(client)
    }

    return undefined
  }

  private getPlayer(
    game: ApiGame,
    username: string
  ): (ApiGame["white"] | ApiGame["black"]) | undefined {
    const normalizedUsername = username.toLowerCase()

    if (game.white.username.toLowerCase() === normalizedUsername)
      return game.white
    if (game.black.username.toLowerCase() === normalizedUsername)
      return game.black

    return undefined
  }

  private parseClientInfo(client: string): DeviceInfo {
    const normalizedClient = client.trim()
    const lower = normalizedClient.toLowerCase()
    const isPhone = /iphone|ipad|ipod|android|mobile|ios|mobi/.test(lower)
    const platform: DeviceInfo["platform"] = isPhone ? "phone" : "pc"
    const icon: DeviceInfo["icon"] = isPhone ? "mdi-cellphone" : "mdi-monitor"

    return {
      platform,
      icon,
      summary: `Player last played on ${platform}`,
      details: this.describeClient(normalizedClient, platform),
      rawClient: normalizedClient
    }
  }

  private describeClient(
    client: string,
    platform: DeviceInfo["platform"]
  ): string {
    const tokens = client
      .replace(/[()]/g, ";")
      .split(";")
      .map((token) => token.trim())
      .filter(Boolean)

    const browserToken = tokens.find((token) =>
      /chrome|firefox|safari|edge|opera|browser/i.test(token)
    )
    const osToken = tokens.find((token) =>
      /windows|mac|macos|linux|chrome os|ios|android|iphone|ipad|ipod/i.test(
        token
      )
    )
    const modelToken = tokens.find((token) =>
      /iphone|ipad|ipod|pixel|galaxy|samsung|xiaomi|oneplus|huawei|android/i.test(
        token
      )
    )

    const parts =
      platform === "phone"
        ? [modelToken, osToken, browserToken]
        : [osToken, browserToken, modelToken]

    const filteredParts = parts.filter(
      (part, index, list) => !!part && list.indexOf(part) === index
    ) as string[]

    return filteredParts.length > 0 ? filteredParts.join(" · ") : client
  }

  /**
   * Transforms a game result string into a corresponding Wld key.
   *
   * @param {string} result - Game result string.
   * @returns {keyof Wld | undefined} A key of the Wld object (e.g., "wins", "loses", "draws") or undefined if the result is unknown.
   */
  transformResult(result: string): keyof Wld {
    switch (result) {
      case "win":
        return "wins"
      case "lose":
      case "checkmated":
      case "resigned":
      case "timeout":
      case "abandoned":
      case "bughousepartnerlose":
        return "loses"
      case "agreed":
      case "timevsinsufficient":
      case "repetition":
      case "stalemate":
      case "insufficient":
      case "50move":
        return "draws"
      default:
        throw new Error(`Cannot transform unknown result: ${result}`)
    }
  }
}

